#!/usr/bin/env bash
# Generated by kubegen from examples/gks.yaml - re-generate instead of editing.
# Creates the gks cluster "prod-gke".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need gcloud https://cloud.google.com/sdk/docs/install
need kubectl https://kubernetes.io/docs/tasks/tools/
need gke-gcloud-auth-plugin https://cloud.google.com/kubernetes-engine/docs/how-to/cluster-access-for-kubectl
[ "$missing" -eq 0 ] || exit 127

echo '==> Checking Google Cloud login'
gcloud auth print-access-token >/dev/null 2>&1 || die "not logged in to Google Cloud; run: gcloud auth login"

echo '==> Creating GKE cluster prod-gke (this takes several minutes)'
gcloud container clusters create prod-gke \
  --project my-gcp-project --location us-central1 \
  --cluster-version 1.33 \
  --release-channel regular \
  --num-nodes 1 \
  --enable-ip-alias \
  --workload-pool my-gcp-project.svc.id.goog \
  --enable-dataplane-v2 \
  --labels env=prod,team=platform \
  --quiet

echo '==> Adding node pool general'
gcloud container node-pools create general --cluster prod-gke \
  --project my-gcp-project --location us-central1 \
  --machine-type e2-standard-4 --num-nodes 1 \
  --disk-size 100 \
  --quiet

echo '==> Adding node pool apps'
gcloud container node-pools create apps --cluster prod-gke \
  --project my-gcp-project --location us-central1 \
  --machine-type e2-standard-8 --num-nodes 1 \
  --enable-autoscaling --min-nodes 1 --max-nodes 4 \
  --node-labels workload=apps \
  --quiet

echo '==> Adding node pool batch'
gcloud container node-pools create batch --cluster prod-gke \
  --project my-gcp-project --location us-central1 \
  --machine-type e2-standard-8 --num-nodes 0 \
  --enable-autoscaling --min-nodes 0 --max-nodes 10 \
  --node-locations us-central1-a,us-central1-b \
  --node-taints workload=batch:NoSchedule \
  --spot \
  --quiet

echo '==> Removing the temporary default-pool'
gcloud container node-pools delete default-pool --cluster prod-gke \
  --project my-gcp-project --location us-central1 \
  --quiet

echo '==> Fetching credentials'
gcloud container clusters get-credentials prod-gke --project my-gcp-project --location us-central1

echo '==> Verifying access to prod-gke'
kubectl get nodes -o wide

echo "Cluster prod-gke is ready."
